scripts.output:
cd -P -- '/srv/beam/workspace' || { echo 'beam: cannot enter workspace /srv/beam/workspace' >&2; exit 62; }
__beam_actual=$(/bin/pwd -P)
if [ "$__beam_actual" != '/srv/beam/workspace' ]; then echo 'beam: workspace path no longer resolves to /srv/beam/workspace' >&2; exit 62; fi
(
  __beam_og_root=$(/bin/pwd -P) || { echo "beam: the workspace is not owned by this handoff — refusing" >&2; exit 52; }
  if [ -L ./.beam ] || [ ! -d ./.beam ]; then echo "beam: the workspace is not owned by this handoff — refusing" >&2; exit 52; fi
  cd -P -- ./.beam 2>/dev/null || { echo "beam: the workspace is not owned by this handoff — refusing" >&2; exit 52; }
  if [ "$(/bin/pwd -P)" != "$__beam_og_root/.beam" ]; then echo "beam: the workspace is not owned by this handoff — refusing" >&2; exit 52; fi
  if [ -L owner ] || [ ! -f owner ]; then echo "beam: the workspace is not owned by this handoff — refusing" >&2; exit 52; fi
  if [ "$(cat owner 2>/dev/null)" != 'beam-workspace-v1 record-1 0123456789abcdef0123456789abcdef' ]; then echo "beam: the workspace is not owned by this handoff — refusing" >&2; exit 52; fi
) || exit $?
__beam_dir=0; __beam_other=0
for __beam_entry in ./.[!.]*; do
  if ! test -e "$__beam_entry" && ! test -L "$__beam_entry"; then continue; fi
  __beam_name=${__beam_entry#./}
  case "$__beam_name" in
    .git) if test ! -L "$__beam_entry" && test -d "$__beam_entry"; then __beam_dir=1; else __beam_other=1; fi ;;
    .[gG][iI][tT]) __beam_other=1 ;;
    .[bB][eE][aA][mM]) if test "$__beam_name" != .beam; then __beam_other=1; fi ;;
  esac
done
if [ "$__beam_other" = 1 ]; then printf '%s\n' other; elif [ "$__beam_dir" = 1 ]; then printf '%s\n' directory; else printf '%s\n' absent; fi
